@Test
public void testSOAPBodyIsntFullyReadWhenNotUsingBinaryRelayBuilder() throws IOException, XMLStreamException {
    SOAPEnvelope envelope = OMXMLBuilderFactory.createSOAPModelBuilder(new StringReader(xml)).getSOAPEnvelope();
    msgCtx.setEnvelope(envelope);
    // Build message when using pass through pipe or binary relay builder
    RelayUtils.buildMessage(msgCtx);
    // Ensure that the payload element is accessible
    assertEquals(payloadQName, msgCtx.getEnvelope().getBody().getFirstElement().getQName());
    // Ensure that the body isn't fully build to support the use of deferred building
    assertFalse(msgCtx.getEnvelope().getBody().isComplete());
}

@Test
public void testBinaryRelayPayloadExpandsToOriginalPayload() throws IOException, XMLStreamException {
    // Transform request soap message into a binary payload
    BinaryRelayBuilder builder = new BinaryRelayBuilder();
    InputStream stream = new ReaderInputStream(new StringReader(xml), UTF8);
    OMElement element = builder.processDocument(stream, "text/xml", msgCtx);
    msgCtx.setEnvelope((SOAPEnvelope) element);
    // Build message when using pass through pipe or binary relay builder
    RelayUtils.buildMessage(msgCtx);
    // Ensure that the binary payload is transformed to the appropriate element
    assertEquals(payloadQName, msgCtx.getEnvelope().getBody().getFirstElement().getQName());
    // Ensure that the body isn't fully build to support the use of deferred building
    assertFalse(msgCtx.getEnvelope().getBody().isComplete());
}

/**
 * Tests CRL Path Validation with the use of a real certificate chain. The verification process
 * will make HTTP calls to remote CRL server URLs extracted from the certificates in the
 * chain. Usually these certificates will not be revoked. So the path validation must be
 * successful to pass the test. In case they are revoked or expired, new certificates should
 * be added to the resources directory and Constants should be modified accordingly. See the
 * interface TestConstants for expiry dates of the certificates.
 *
 * @throws Exception
 */
@Test
@Ignore("Unit tests with builtin expiration date are bad")
public void testCRLPathValidation() throws Exception {
    //Add BouncyCastle as Security Provider.
    Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());
    Utils utils = new Utils();
    X509Certificate[] certificates = utils.getRealCertificateChain();
    crlPathValidation(certificates);
}

/**
 * Tests CRL path validation with fake certificates. The path validation should fail since
 * they are fake and do not contain proper information.
 *
 * @throws Exception
 */
@Test
public void testCRLPathValidationWithFakeCerts() throws Exception {
    //Add BouncyCastle as Security Provider.
    Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());
    Utils utils = new Utils();
    X509Certificate[] fakeCertificates = utils.getFakeCertificateChain();
    Throwable throwable = null;
    try {
        crlPathValidation(fakeCertificates);
    } catch (CertificateVerificationException e) {
        //Path Verification Should fail. So this catch block should be called.
        throwable = e;
    }
    assertNotNull(throwable);
}

